+/**
+ * @brief Dump all K cache entries from HBM for a token range and layer
+ * @param start_token First token position to dump
+ * @param end_token Last token position to dump (inclusive)
+ * @param layer Layer number
+ * @param device_idx Device index
+ * @param head_size Size of each head
+ * @param n_kv_heads Number of KV heads
+ * @param output_file Path to output JSON file
+ */
+inline void dump_k_cache_from_hbm(uint32_t start_token,
+    uint32_t end_token,
+    size_t layer,
+    size_t device_idx,
+    size_t head_size,
+    size_t n_kv_heads,
+    const std::string& output_file) {
+  auto hwkv = get_hwkv();
+  PosDevice* dev = devices[device_idx];
+  uint64_t hbm_base_addr = hwkv->hw_k_map[device_idx];
+
+  std::ofstream out(output_file, std::ios::out | std::ios::trunc);
+  if (!out.is_open()) {
+    spdlog::error("Failed to open {} for writing K cache dump", output_file);
+    return;
+  }
+
+  // Allocate temporary storage for unshuffled K data
+  std::vector<std::vector<bf16>> k_heads(n_kv_heads);
+  std::vector<bf16*> k_ptrs(n_kv_heads);
+  for (size_t head = 0; head < n_kv_heads; ++head) {
+    k_heads[head].resize(head_size);
+    k_ptrs[head] = k_heads[head].data();
+  }
+
+  out << "{\n";
+  out << fmt::format("  \"device\": {},\n", device_idx);
+  out << fmt::format("  \"layer\": {},\n", layer);
+  out << fmt::format("  \"start_token\": {},\n", start_token);
+  out << fmt::format("  \"end_token\": {},\n", end_token);
+  out << fmt::format("  \"head_size\": {},\n", head_size);
+  out << fmt::format("  \"n_kv_heads\": {},\n", n_kv_heads);
+  out << "  \"fetchers\": [\n";
+
+  for (size_t pdc = 0; pdc < dev->num_fetchers; pdc++) {
+    out << "    {\n";
+    out << fmt::format("      \"fetcher\": {},\n", pdc);
+    out << "      \"tokens\": [\n";
+
+    for (uint32_t tok = start_token; tok <= end_token; tok++) {
+      // Calculate which fetcher this token belongs to based on position
+      // K cache: fetcher = (position / 4) % num_fetchers
+      uint32_t fetcher = (tok / 4) % dev->num_fetchers;
+      if (fetcher != pdc) continue;
+
+      uint64_t page_addr = get_hw_page_addr(tok, layer, hbm_base_addr);
+      // Calculate offset within the page for this token
+      size_t pos_in_block = tok % 4;
+
+      // Each K entry is: 8 heads * head_size * sizeof(bf16)
+      size_t k_entry_size = 8 * head_size * sizeof(bf16);
+      size_t offset = pos_in_block * k_entry_size;
+
+      // Get virtual address for this fetcher
+      uint64_t vhbm_addr =
+          static_cast<uint64_t>(page_addr) + dev->vhbm_map[pdc].addr + offset;
+      bf16* k_data = reinterpret_cast<bf16*>(vhbm_addr);
+
+      // Create k_hwcacheblock structure pointing to HBM data
+      k_hwcacheblock k_block;
+      for (size_t head = 0; head < 8; head++) {
+        k_block.positions[pos_in_block][head] = k_data + (head * head_size);
+      }
+
+      // Use unshuffle_k_entry to extract linear per-head K data
+      unshuffle_k_entry(&k_block, pos_in_block, k_ptrs.data(), n_kv_heads, head_size);
+
+      out << "        {\n";
+      out << fmt::format("          \"token\": {},\n", tok);
+      out << "          \"heads\": [\n";
+
+      for (size_t head = 0; head < n_kv_heads && head < 8; head++) {
+        out << "            {\n";
+        out << fmt::format("              \"head\": {},\n", head);
+        out << "              \"data\": [";
+
+        for (size_t i = 0; i < head_size; i++) {
+          if (i > 0) out << ", ";
+          uint16_t val = *reinterpret_cast<uint16_t*>(&k_heads[head][i]);
+          out << fmt::format("\"0x{:04x}\"", val);
+        }
+
+        out << "]\n";
+        out << "            }";
+        if (head < n_kv_heads - 1 && head < 7) out << ",";
+        out << "\n";
+      }
+
+      out << "          ]\n";
+      out << "        }";
+      if (tok < end_token) {
+        // Check if there are more tokens for this fetcher
+        bool has_more = false;
+        for (uint32_t t = tok + 1; t <= end_token; t++) {
+          if ((t / 4) % dev->num_fetchers == pdc) {
+            has_more = true;
+            break;
+          }
+        }
+        if (has_more) out << ",";
+      }
+      out << "\n";
+    }
+
+    out << "      ]\n";
+    out << "    }";
+    if (pdc < dev->num_fetchers - 1) out << ",";
+    out << "\n";
+  }
+
+  out << "  ]\n";
+  out << "}\n";
+  out.close();
+  spdlog::info("K cache dump written to {}", output_file);
+}
