+/**
+ * @brief Dump all V cache entries from HBM for a token range and layer
+ * @param start_token First token position to dump
+ * @param end_token Last token position to dump (inclusive)
+ * @param layer Layer number
+ * @param device_idx Device index
+ * @param head_size Size of each head
+ * @param n_kv_heads Number of KV heads
+ * @param output_file Path to output JSON file
+ */
+inline void dump_v_cache_from_hbm(uint32_t start_token,
+    uint32_t end_token,
+    size_t layer,
+    size_t device_idx,
+    size_t head_size,
+    size_t n_kv_heads,
+    const std::string& output_file) {
+  auto hwkv = get_hwkv();
+  PosDevice* dev = devices[device_idx];
+  uint64_t hbm_base_addr = hwkv->hw_v_map[device_idx];
+
+  std::ofstream out(output_file, std::ios::out | std::ios::trunc);
+  if (!out.is_open()) {
+    spdlog::error("Failed to open {} for writing V cache dump", output_file);
+    return;
+  }
+
+  out << "{\n";
+  out << fmt::format("  \"device\": {},\n", device_idx);
+  out << fmt::format("  \"layer\": {},\n", layer);
+  out << fmt::format("  \"start_token\": {},\n", start_token);
+  out << fmt::format("  \"end_token\": {},\n", end_token);
+  out << fmt::format("  \"head_size\": {},\n", head_size);
+  out << fmt::format("  \"n_kv_heads\": {},\n", n_kv_heads);
+  out << "  \"fetchers\": [\n";
+
+  // Allocate temporary storage for unshuffled V data
+  std::vector<std::vector<bf16>> v_heads(n_kv_heads);
+  std::vector<bf16*> v_ptrs(n_kv_heads);
+  for (size_t head = 0; head < n_kv_heads; ++head) {
+    v_heads[head].resize(head_size);
+    v_ptrs[head] = v_heads[head].data();
+  }
+
+  for (size_t pdc = 0; pdc < dev->num_fetchers; pdc++) {
+    out << "    {\n";
+    out << fmt::format("      \"fetcher\": {},\n", pdc);
+    out << "      \"tokens\": [\n";
+
+    for (uint32_t tok = start_token; tok <= end_token; tok++) {
+      // V cache: tokens are distributed by fetcher similar to K cache
+      uint32_t fetcher = (tok / 4) % dev->num_fetchers;
+      if (fetcher != pdc) continue;
+
+      uint64_t page_addr = get_hw_page_addr(tok, layer, hbm_base_addr);
+      size_t pos_in_block = tok % 4;
+      size_t page_pos = tok % hwkv_tok_per_page;
+      size_t page_block = page_pos / 4;
+      uint64_t adjusted_addr =
+          page_addr +
+          (page_block * (4 * (hwkv_pchannel_page_size_B / hwkv_tok_per_page)));
+
+      // Create a v_hwcacheblock structure that maps to HBM data across all fetchers
+      v_hwcacheblock v_block;
+      for (size_t f = 0; f < dev->num_fetchers; ++f) {
+        uint64_t vhbm_addr =
+            static_cast<uint64_t>(adjusted_addr) + dev->vhbm_map[f].addr;
+        bf16* v_base = reinterpret_cast<bf16*>(vhbm_addr);
+        // Map the HBM data to the v_hwcacheblock structure
+        // Each fetcher has data for 4 rows (head pairs), 4 positions, 8 bf16 elements
+        for (size_t row = 0; row < 4; ++row) {
+          for (size_t p = 0; p < 4; ++p) {
+            v_block.positions[f][row][p] = v_base + (row * 4 * 8) + (p * 8);
+          }
+        }
+      }
+
+      // Use unshuffle_v_entry to extract per-head V data
+      unshuffle_v_entry(
+          &v_block, pos_in_block, device_idx, v_ptrs.data(), n_kv_heads, head_size);
+
+      out << "        {\n";
+      out << fmt::format("          \"token\": {},\n", tok);
+      out << "          \"heads\": [\n";
+
+      for (size_t head = 0; head < n_kv_heads; head++) {
+        out << "            {\n";
+        out << fmt::format("              \"head\": {},\n", head);
+        out << "              \"data\": [";
+
+        for (size_t i = 0; i < head_size; i++) {
+          if (i > 0) out << ", ";
+          uint16_t val = *reinterpret_cast<uint16_t*>(&v_heads[head][i]);
+          out << fmt::format("\"0x{:04x}\"", val);
+        }
+
+        out << "]\n";
+        out << "            }";
+        if (head < n_kv_heads - 1) out << ",";
+        out << "\n";
+      }
+
+      out << "          ]\n";
+      out << "        }";
+      if (tok < end_token) {
+        // Check if there are more tokens for this fetcher
+        bool has_more = false;
+        for (uint32_t t = tok + 1; t <= end_token; t++) {
+          if ((t / 4) % dev->num_fetchers == pdc) {
+            has_more = true;
+            break;
+          }
+        }
+        if (has_more) out << ",";
+      }
+      out << "\n";
+    }
+
+    out << "      ]\n";
+    out << "    }";
+    if (pdc < dev->num_fetchers - 1) out << ",";
+    out << "\n";
+  }
+
+  out << "  ]\n";
+  out << "}\n";
+  out.close();
+  spdlog::info("V cache dump written to {}", output_file);
+}
