+/**
+ * @brief Helper to format float as hex or special string for NaN/Infinity
+ */
+inline std::string float_to_hex_or_special(float val) {
+  if (std::isnan(val)) {
+    return "\"NaN\"";
+  } else if (std::isinf(val)) {
+    return val > 0 ? "\"+Infinity\"" : "\"-Infinity\"";
+  } else {
+    uint32_t hex_val = *reinterpret_cast<uint32_t*>(&val);
+    return fmt::format("\"0x{:08x}\"", hex_val);
+  }
+}
