+// Returns true if hardware attention results should be forwarded.
+// Returns false if software attention should produce the output.
+//
+// The environment variable is read exactly once, at first call. Call this
+// early during model initialization to force reading before threads are spawned.
+//   - default OFF: USE_HW_ATTN=1 enables, USE_HW_ATTN=0 or 'unset' disables
+inline bool fwd_hw_attn_enabled() {
+  static const bool val = [] {
+    const char* v = std::getenv("USE_HW_ATTN");
+    if (v != nullptr) {
+      return std::atoi(v) > 0;
+    }
+    return false;  // HW attn off by default
+  }();
+  return val;
+}
