+    wrapping = true;
+  }
+  for (size_t idx = 0; idx < limit; idx++) {
+    if (!wrapping) {
+      if (!foundfirst && (sarr[idx] == tval)) {  // find the first match
+        first = idx;
+        foundfirst = true;
+        continue;
+      }
+      if (foundfirst && (sarr[idx] != tval)) {  // find the last match
+        last = idx - 1;
+        break;
+      }
+    } else {
+      if (!foundfirst && (sarr[idx] != tval)) {  // in wrapping, last is first
+        last = idx - 1;
+        foundfirst = true;
+        continue;
+      }
+      if (foundfirst && (sarr[idx] == tval)) {
+        first = idx;
+        break;
+      }
+    }
+  }
+
+  if (wrapping) {
+    len = (limit - first) + last + 1;
+  } else {
+    len = last - first + 1;
+  }
+
