+// DMA arena allocator implementation. See doc/pos_heap_v2.md.
+// Phase 3: ASAN integration (chunk-wide poison; per-slot unpoison of
+// caller's requested_size; centralized unpoison/repoison around the
+// free-list link), HEAP_V2_SHADOW shadow map (per-class shard,
+// exact-size validation), and dump_profile diagnostic.
+// Phase 4 wires this into pos_heap_v2 as a drop-in for legacy
+// pos_heap.
+
+#include <cstring>
+
+#include <sanitizer/asan_interface.h>
+#include <spdlog/spdlog.h>
+
+#include "common/assert.hpp"
+#include "system/heap_v2.hpp"
+
+#ifdef HEAP_V2_SHADOW
+#include <array>
+#include <cstdio>
+#include <cstdlib>
+#include <map>
+#include <utility>
+#endif
+
+namespace tron::hardware::heap_v2 {
+
+namespace {
+
+// --------------------------------------------------------------------------
+// Within-slab slot management
+// --------------------------------------------------------------------------
+// Slots are picked by either popping the free-list (returned-slot
+// stack, embedded in slot 0..3 of each free slot) or bumping the
+// `next_uninit_idx` cursor. Lazy initialization: slots indexed
+// >= next_uninit_idx have never been written and contribute no
+// per-slot metadata until allocated.
+
+// Pointer to slot `idx` within slab `s`.
+inline uint8_t* slot_ptr(slab_t const& s, uint32_t idx) noexcept {
+  return s.base + idx * slot_size_for(s.class_idx);
+}
+
+// Convert a pointer back to its slot index within its slab.
+inline uint32_t slot_idx_of(slab_t const& s, void* p) noexcept {
+  return static_cast<uint32_t>(
+      (reinterpret_cast<uintptr_t>(p) - reinterpret_cast<uintptr_t>(s.base)) /
+      slot_size_for(s.class_idx));
+}
+
+// Free-list link manipulation. The link is a uint32_t (4 bytes), but
+// the slot's first 8 bytes are reserved for it to match ASAN's
+// 8-byte shadow granularity. Free slots are poisoned by deallocate,
+// so the link helpers must unpoison-op-repoison around the link
+// granule. See doc/pos_heap_v2.md §"ASAN integration".
+constexpr size_t LINK_GRANULE = 8;
+static_assert(sizeof(uint32_t) <= LINK_GRANULE);
+
+inline uint32_t slot_link_read(void* link_addr) noexcept {
+  ASAN_UNPOISON_MEMORY_REGION(link_addr, LINK_GRANULE);
+  uint32_t next;
+  std::memcpy(&next, link_addr, sizeof(next));
+  ASAN_POISON_MEMORY_REGION(link_addr, LINK_GRANULE);
+  return next;
+}
+
+inline void slot_link_write(void* link_addr, uint32_t next_idx) noexcept {
+  ASAN_UNPOISON_MEMORY_REGION(link_addr, LINK_GRANULE);
+  std::memcpy(link_addr, &next_idx, sizeof(next_idx));
+  ASAN_POISON_MEMORY_REGION(link_addr, LINK_GRANULE);
+}
+
+// Acquire a free slot from `s`. Returns INVALID_IDX if the slab is
+// full. Increments `s.nr_live`. Caller is responsible for the
+// `state` transition (PARTIAL → FULL) when the slab fills.
+uint32_t slab_acquire_slot(slab_t& s) noexcept {
+  uint32_t idx;
+  if (s.free_head_idx != INVALID_IDX) {
+    idx = s.free_head_idx;
+    s.free_head_idx = slot_link_read(slot_ptr(s, idx));
+  } else if (s.next_uninit_idx < s.total_slots) {
+    idx = s.next_uninit_idx++;
+  } else {
+    return INVALID_IDX;
+  }
+  s.nr_live++;
+  return idx;
+}
+
+// Push a slot back onto the slab's free-list. Decrements
+// `s.nr_live`. Caller is responsible for the `state` transitions
+// (FULL → PARTIAL, PARTIAL → empty).
+void slab_release_slot(slab_t& s, uint32_t idx) noexcept {
+  slot_link_write(slot_ptr(s, idx), s.free_head_idx);
+  s.free_head_idx = idx;
+  s.nr_live--;
+}
+
+// Initialize a slab's per-class fields. The base, hugepage, and
+// (for sub-slabs) the slot_size are class-dependent and are reset
+// each time the slab is assigned to a class.
+void slab_init_for_class(slab_t& s,
+    hugepage_t* hp,
+    uint8_t* base,
+    uint8_t class_idx,
+    size_t slab_bytes) noexcept {
+  s.base = base;
+  s.hugepage = hp;
+  s.class_idx = class_idx;
+  s.state = SLAB_PARTIAL;
+  s.total_slots = static_cast<uint32_t>(slab_bytes / slot_size_for(class_idx));
+  s.next_uninit_idx = 0;
+  s.free_head_idx = INVALID_IDX;
+  s.nr_live = 0;
+  s.prev_in_class = nullptr;
+  s.next_in_class = nullptr;
+}
+
+// --------------------------------------------------------------------------
+// Class arena list manipulation (intrusive doubly-linked)
+// --------------------------------------------------------------------------
+
+// Splice `s` onto the front of `head`. Caller holds arena.mu.
+void list_push_front(slab_t*& head, slab_t* s) noexcept {
+  s->prev_in_class = nullptr;
+  s->next_in_class = head;
+  if (head) head->prev_in_class = s;
+  head = s;
+}
+
+// Splice `s` out of its current list. Caller holds arena.mu.
+void list_unlink(slab_t*& head, slab_t* s) noexcept {
+  if (s->prev_in_class)
+    s->prev_in_class->next_in_class = s->next_in_class;
+  else
+    head = s->next_in_class;
+  if (s->next_in_class) s->next_in_class->prev_in_class = s->prev_in_class;
+  s->prev_in_class = nullptr;
+  s->next_in_class = nullptr;
+}
+
+// --------------------------------------------------------------------------
+// Per-class arena allocate / deallocate
+// --------------------------------------------------------------------------
+
+// Acquire a fresh slab for `arena.class_idx` from the pool. Caller
+// holds arena.mu. Returns nullptr on pool exhaustion.
+slab_t* arena_acquire_fresh_slab(class_arena_t& arena, slab_pool_t& pool) noexcept {
+  if (class_is_small(arena.class_idx)) return pool.acquire_sub_slab(arena.class_idx);
+  return pool.acquire_large(arena.class_idx);
+}
+
+// Allocate a slot from `arena`, possibly pulling a fresh slab from
+// `pool`. Returns nullptr on pool exhaustion. `requested_size` is the
+// caller's pre-routing size, used for ASAN unpoison and (under
+// HEAP_V2_SHADOW) shadow-map insertion.
+void* arena_allocate(class_arena_t& arena,
+    slab_pool_t& pool,
+    size_t requested_size
