+// pos_heap_v2::deallocate after resolving slab_for(p). `requested_size`
+// is the caller's deallocate size; under HEAP_V2_SHADOW it must match
+// the recorded requested_size exactly.
+void arena_deallocate(class_arena_t& arena,
+    slab_pool_t& pool,
+    slab_t* s,
+    void* ptr,
+    [[maybe_unused]] size_t requested_size) noexcept {
+  std::lock_guard guard(arena.mu);
+
