+// --------------------------------------------------------------------------
+// Within-slab slot management
+// --------------------------------------------------------------------------
+// Slots are picked by either popping the free-list (returned-slot
+// stack, embedded in slot 0..3 of each free slot) or bumping the
+// `next_uninit_idx` cursor. Lazy initialization: slots indexed
+// >= next_uninit_idx have never been written and contribute no
+// per-slot metadata until allocated.
+
+// Pointer to slot `idx` within slab `s`.
+inline uint8_t* slot_ptr(slab_t const& s, uint32_t idx) noexcept {
+  return s.base + idx * slot_size_for(s.class_idx);
+}
+
+// Convert a pointer back to its slot index within its slab.
+inline uint32_t slot_idx_of(slab_t const& s, void* p) noexcept {
+  return static_cast<uint32_t>(
+      (reinterpret_cast<uintptr_t>(p) - reinterpret_cast<uintptr_t>(s.base)) /
+      slot_size_for(s.class_idx));
+}
+
+// Free-list link manipulation. The link is a uint32_t (4 bytes), but
+// the slot's first 8 bytes are reserved for it to match ASAN's
+// 8-byte shadow granularity. Free slots are poisoned by deallocate,
+// so the link helpers must unpoison-op-repoison around the link
+// granule. See doc/pos_heap_v2.md §"ASAN integration".
+constexpr size_t LINK_GRANULE = 8;
+static_assert(sizeof(uint32_t) <= LINK_GRANULE);
+
+inline uint32_t slot_link_read(void* link_addr) noexcept {
+  ASAN_UNPOISON_MEMORY_REGION(link_addr, LINK_GRANULE);
+  uint32_t next;
+  std::memcpy(&next, link_addr, sizeof(next));
+  ASAN_POISON_MEMORY_REGION(link_addr, LINK_GRANULE);
+  return next;
+}
+
+inline void slot_link_write(void* link_addr, uint32_t next_idx) noexcept {
+  ASAN_UNPOISON_MEMORY_REGION(link_addr, LINK_GRANULE);
+  std::memcpy(link_addr, &next_idx, sizeof(next_idx));
+  ASAN_POISON_MEMORY_REGION(link_addr, LINK_GRANULE);
+}
+
+// Acquire a free slot from `s`. Returns INVALID_IDX if the slab is
+// full. Increments `s.nr_live`. Caller is responsible for the
+// `state` transition (PARTIAL → FULL) when the slab fills.
+uint32_t slab_acquire_slot(slab_t& s) noexcept {
+  uint32_t idx;
+  if (s.free_head_idx != INVALID_IDX) {
+    idx = s.free_head_idx;
+    s.free_head_idx = slot_link_read(slot_ptr(s, idx));
+  } else if (s.next_uninit_idx < s.total_slots) {
+    idx = s.next_uninit_idx++;
+  } else {
+    return INVALID_IDX;
+  }
+  s.nr_live++;
+  return idx;
+}
+
+// Push a slot back onto the slab's free-list. Decrements
+// `s.nr_live`. Caller is responsible for the `state` transitions
+// (FULL → PARTIAL, PARTIAL → empty).
+void slab_release_slot(slab_t& s, uint32_t idx) noexcept {
+  slot_link_write(slot_ptr(s, idx), s.free_head_idx);
+  s.free_head_idx = idx;
+  s.nr_live--;
+}
+
+// Initialize a slab's per-class fields. The base, hugepage, and
+// (for sub-slabs) the slot_size are class-dependent and are reset
+// each time the slab is assigned to a class.
+void slab_init_for_class(slab_t& s,
+    hugepage_t* hp,
+    uint8_t* base,
+    uint8_t class_idx,
+    size_t slab_bytes) noexcept {
+  s.base = base;
+  s.hugepage = hp;
+  s.class_idx = class_idx;
+  s.state = SLAB_PARTIAL;
+  s.total_slots = static_cast<uint32_t>(slab_bytes / slot_size_for(class_idx));
+  s.next_uninit_idx = 0;
+  s.free_head_idx = INVALID_IDX;
+  s.nr_live = 0;
+  s.prev_in_class = nullptr;
+  s.next_in_class = nullptr;
+}
+
+// --------------------------------------------------------------------------
+// Class arena list manipulation (intrusive doubly-linked)
+// --------------------------------------------------------------------------
+
+// Splice `s` onto the front of `head`. Caller holds arena.mu.
+void list_push_front(slab_t*& head, slab_t* s) noexcept {
+  s->prev_in_class = nullptr;
+  s->next_in_class = head;
+  if (head) head->prev_in_class = s;
+  head = s;
+}
+
+// Splice `s` out of its current list. Caller holds arena.mu.
+void list_unlink(slab_t*& head, slab_t* s) noexcept {
+  if (s->prev_in_class)
+    s->prev_in_class->next_in_class = s->next_in_class;
+  else
+    head = s->next_in_class;
+  if (s->next_in_class) s->next_in_class->prev_in_class = s->prev_in_class;
+  s->prev_in_class = nullptr;
+  s->next_in_class = nullptr;
+}
+
+// --------------------------------------------------------------------------
+// Per-class arena allocate / deallocate
+// --------------------------------------------------------------------------
+
+// Acquire a fresh slab for `arena.class_idx` from the pool. Caller
+// holds arena.mu. Returns nullptr on pool exhaustion.
+slab_t* arena_acquire_fresh_slab(class_arena_t& arena, slab_pool_t& pool) noexcept {
+  if (class_is_small(arena.class_idx)) return pool.acquire_sub_slab(arena.class_idx);
+  return pool.acquire_large(arena.class_idx);
+}
+
+// Allocate a slot from `arena`, possibly pulling a fresh slab from
+// `pool`. Returns nullptr on pool exhaustion. `requested_size` is the
+// caller's pre-routing size, used for ASAN unpoison and (under
+// HEAP_V2_SHADOW) shadow-map insertion.
+void* arena_allocate(class_arena_t& arena,
+    slab_pool_t& pool,
+    size_t requested_size
+#ifdef HEAP_V2_SHADOW
+    ,
+    void* caller_pc,
+    void* caller_pc_2
+#endif
+    ) noexcept {
+  std::lock_guard guard(arena.mu);
+
+  slab_t* s = arena.partial_head;
+  if (!s) {
+    s = arena_acquire_fresh_slab(arena, pool);
+    if (!s) return nullptr;
+    list_push_front(arena.partial_head, s);
+    arena.partial_count.fetch_add(1, std::memory_order_relaxed);
+  }
+
+  uint32_t idx = slab_acquire_slot(*s);
+  TRON_ASSERT(idx != INVALID_IDX);
+  void* ptr = slot_ptr(*s, idx);
+  arena.nr_live.fetch_add(1, std::memory_order_relaxed);
+
+  // PARTIAL → FULL transition if this allocation filled the slab.
+  if (s->nr_live == s->total_slots) {
+    list_unlink(arena.partial_head, s);
+    arena.partial_count.fetch_sub(1, std::memory_order_relaxed);
+    s->state = SLAB_FULL;
+    list_push_front(arena.full_head, s);
+    arena.full_count.fetch_add(1, std::memory_order_relaxed);
+  }
+
+#ifdef HEAP_V2_SHADOW
+  arena.allocations.insert(
+      {ptr, alloc_info{requested_size, slot_size_for(arena.class_idx), arena.class_idx,
+                caller_pc, caller_pc_2}});
+#endif
+
+  // Open the caller's requested window. The rest of the slot stays
+  // poisoned so OOB writes past `requested_size` are caught.
+  ASAN_UNPOISON_MEMORY_REGION(ptr, requested_size);
+
+  return ptr;
+}
+
+// Release `ptr` (known to be in `s`) back to `arena`. Caller is
+// pos_heap_v2::deallocate after resolving slab_for(p). `requested_size`
+// is the caller's deallocate size; under HEAP_V2_SHADOW it must match
+// the recorded requested_size exactly.
+void arena_deallocate(class_arena_t& arena,
+    slab_pool_t& pool,
+    slab_t* s,
+    void* ptr,
+    [[maybe_unused]] size_t requested_size) noexcept {
+  std::lock_guard guard(arena.mu);
+
+#ifdef HEAP_V2_SHADOW
+  auto it = arena.allocations.find(ptr);
+  TRON_ASSERT(it != arena.allocations.end(),
+      "heap_v2: deallocate of unknown pointer {} (class {})", ptr, arena.class_idx);
+  TRON_ASSERT(it->second.requested_size == requested_size,
+      "heap_v2: deallocate size mismatch for {}: passed {}, recorded {}", ptr,
+      requested_size, it->second.requested_size);
+  arena.allocations.erase(it);
+#endif
+
+  size_t slot_size = slot_size_for(s->class_idx);
+  // Repoison the whole slot. slab_release_slot then writes the link,
+  // unpoisoning and repoisoning just the link granule internally.
+  ASAN_POISON_MEMORY_REGION(ptr, slot_size);
+
+  uint32_t idx = slot_idx_of(*s, ptr);
+  slab_release_slot(*s, idx);
+  arena.nr_live.fetch_sub(1, std::memory_order_relaxed);
+
+  // FULL → PARTIAL transition if this dealloc reopened a slot.
+  if (s->state == SLAB_FULL) {
+    list_unlink(arena.full_head, s);
+    arena.full_count.fetch_sub(1, std::memory_order_relaxed);
+    s->state = SLAB_PARTIAL;
+    list_push_front(arena.partial_head, s);
+    arena.partial_count.fetch_add(1, std::memory_order_relaxed);
+  }
+
+  // PARTIAL → empty: cache one empty slab per SMALL-class arena to
+  // avoid pool.mu churn in workloads where threads hold a single slot
+  // in flight (every alloc+dealloc would otherwise lock pool.mu twice
+  // — once to release on dealloc, once to acquire on the next
+  // alloc). The reserve is the slab we just drained, left in
+  // partial_head with state still SLAB_PARTIAL but nr_live == 0.
+  // The next allocate on this class reuses it without touching the
+  // pool. See doc/pos_heap_v2.md §"Open questions" Q1.
+  //
+  // Caching is restricted to SMALL classes: pinning a sub-slab is
+  // 16 MiB; pinning a LARGE slab is a whole 1 GiB hugepage, far too
+  // expensive to hold idle. Release LARGE slabs immediately.
+  //
+  // When a cache holds the slab, the pool's view shows nr_assigned
+  // counters as if the slab is still in use. The reserve is reclaimed
+  // by drain_reserves(), invoked automatically by the public
+  // allocate path on first failure and on demand by tests that need
+  // exact post-drain counter state.
+  if (s->nr_live == 0) {
+    bool eligible_for_cache = class_is_small(s->class_idx) &&
+                              arena.partial_count.load(std::memory_order_relaxed) == 1;
+    if (!eligible_for_cache) {
+      list_unlink(arena.partial_head, s);
+      arena.partial_count.fetch_sub(1, std::memory_order_relaxed);
+      s->state = SLAB_FREE;
+      pool.release(s);
+    }
+    // else: leave s in partial_head as the cached empty.
+  }
+}
+
+}  // namespace
+
+// --------------------------------------------------------------------------
+// pos_heap_v2 lifecycle
+// --------------------------------------------------------------------------
+
+pos_heap_v2::pos_heap_v2() noexcept {
+  for (uint8_t i = 0; i < NUM_CLASSES; ++i) {
+    arenas[i].class_idx = i;
+  }
+}
+
+void pos_heap_v2::expand(tron::mmap_ptr chunk_mmap) noexcept {
+  size_t size = chunk_mmap.get_deleter().size;
+  TRON_ASSERT_GE(size, hugepage_size);
+  TRON_ASSERT_EQ(size % hugepage_size, 0);
+
+  size_t n_hp = size / hugepage_size;
+  uint8_t* base = static_cast<uint8_t*>(chunk_mmap.get());
+  TRON_ASSERT(base != nullptr, "heap_v2: expand called with null chunk base");
+  TRON_ASSERT_EQ(reinterpret_cast<uintptr_t>(base) % hugepage_size, 0);
+
+  std::lock_guard guard(pool.mu);
+
+  // Construct the chunk. Each hugepage starts in HUGEPAGE_FREE state.
+  chunk_t c{};
+  c.base = base;
+  c.size = size;
+  c.mmap = std::move(chunk_mmap);
+  c.hugepages.resize(n_hp);
+  for (size_t i = 0; i < n_hp; ++i) {
+    hugepage_t& hp = c.hugepages[i];
+    hp.base = base + i * hugepage_size;
+    hp.mode = HUGEPAGE_FREE;
+    hp.nr_assigned_sub_slabs = 0;
+    hp.next_free = nullptr;
+  }
+  pool.chunks.push_back(std::move(c));
+
+  // Thread the hugepages onto the free-hugepage list after the
+  // vector push so pointers don't get invalidated by reallocation.
+  // Push from high to low so the lowest-offset hugepage is at the
+  // head: matches legacy pos_heap's low-address-first allocation
+  // order. Reproducible workaround for an unidentified bug — when
+  // the first DMA descriptor ring lands at a high offset (e.g.
+  // hugepage 15 with the natural LIFO ordering), the FPGA's first
+  // DMA transfer hangs indefinitely on real hardware (rinzler with
+  // llama-3.1-8b on andoria-06). Reversing the push order so the
+  // descriptor ring lands at a low offset avoids the hang. Once
+  // the heap is in steady state, allocations at high offsets DMA
+  // fine (validated to 23+ GiB live KV cache spanning ~30
+  // hugepages). The trigger is specifically the *first* DMA, not
+  // the IOVA range per se. See TODO: open question for follow-up.
+  chunk_t& added = pool.chunks.back();
+  for (size_t i = n_hp; i-- > 0;) {
+    hugepage_t& hp = added.hugepages[i];
+    hp.next_free = pool.free_hugepage_head;
+    pool.free_hugepage_head = &hp;
+  }
+
+  pool.nr_hugepages += n_hp;
+  pool.nr_free_hugepages.fetch_add(
+      static_cast<uint32_t>(n_hp), std::memory_order_relaxed);
+
+  // Whole chunk starts poisoned. allocate unpoisons per-slot only
+  // the caller's requested window; free slots remain poisoned, with
+  // their free-list link granule briefly unpoisoned by the link
+  // helpers around each read/write.
+  ASAN_POISON_MEMORY_REGION(base, size);
+
+  spdlog::info("heap_v2: pool expanded by {} hugepages ({} GiB)", n_hp,
+      static_cast<double>(size) / hugepage_size);
+}
+
+// --------------------------------------------------------------------------
+// pos_heap_v2 public allocate / deallocate
+// --------------------------------------------------------------------------
+
+void* pos_heap_v2::allocate(size_t size) noexcept {
+  return allocate(size, size);
+}
+
+void* pos_heap_v2::allocate(size_t size, size_t alignment) noexcept {
+  // Capture caller frames at the public API boundary. Used for the
+  // OOM log line (so the failing call site shows in the error
+  // without requiring HEAP_V2_SHADOW) and for the shadow-map record
+  // when HEAP_V2_SHADOW is on. __builtin_return_address(1) requires
+  // -fno-omit-frame-pointer, which this build uses; the
+  // -Wframe-address warning is suppressed because we treat any
+  // failure as nullptr-equivalent — addr2line resolves offline.
+#pragma GCC diagnostic push
+#pragma GCC diagnostic ignored "-Wframe-address"
+  void* caller_pc = __builtin_return_address(0);
+  void* caller_pc_2 = __builtin_return_address(1);
+#pragma GCC diagnostic pop
+
+  uint8_t cls = class_for(size, alignment);
+  if (cls >= NUM_CLASSES) return nullptr;  // > 1 GiB request
+  // For LARGE classes, drain cached SMALL reserves up front. The cache
+  // pins SMALL hugepages during peak workload (one cached sub-slab can
+  // prevent its host hugepage from being eagerly reaped), which can
+  // crowd out the LARGE acquire. LARGE allocs are rare and slow, so
+  // paying the per-arena lock walk here is cheap compared to the
+  // alternative (OOM-ing with cached headroom still held).
+  if (!class_is_small(cls)) drain_reserves();
+  void* p = arena_allocate(arenas[cls], pool, size
+#ifdef HEAP_V2_SHADOW
+      ,
+      caller_pc, caller_pc_2
+#endif
+  );
+  if (!p) {
+    // Pool exhausted from this arena's view. Drain any cached empty
+    // slabs held by other SMALL-class arenas and retry once. This
+    // is the "reclaimed before any OOM" guarantee from
+    // doc/pos_heap_v2.md §"Open questions" Q1.
+    drain_reserves();
+    p = arena_allocate(arenas[cls], pool, size
+#ifdef HEAP_V2_SHADOW
+        ,
+        caller_pc, caller_pc_2
+#endif
+    );
+  }
+  if (!p) {
+    spdlog::error(
+        "heap_v2: out of memory; requested {} bytes (class {}), caller pc={} pc_2={}",
+        size, cls, caller_pc, caller_pc_2);
+    spdlog::error("heap_v2 pool: nr_hugepages={} free={} large={} small={} "
+                  "free_sub_slabs={} assigned_slabs={}",
+        pool.nr_hugepages, pool.nr_free_hugepages.load(std::memory_order_relaxed),
+        pool.nr_large_hugepages.load(std::memory_order_relaxed),
+        pool.nr_small_hugepages.load(std::memory_order_relaxed),
+        pool.nr_free_sub_slabs.load(std::memory_order_relaxed),
+        pool.nr_assigned_slabs.load(std::memory_order_relaxed));
+    for (size_t i = 0; i < NUM_CLASSES; ++i) {
+      uint64_t nr_live = arenas[i].nr_live.load(std::memory_order_relaxed);
+      uint32_t partial = arenas[i].partial_count.load(std::memory_order_relaxed);
+      uint32_t full = arenas[i].full_count.load(std::memory_order_relaxed);
+      if (nr_live == 0 && partial == 0 && full == 0) continue;
+      spdlog::error("heap_v2 class {:2}: slot={:>8} KiB live={:<8} partial={} full={}",
+          i, slot_size_for(static_cast<uint8_t>(i)) / 1024, nr_live, partial, full);
+    }
+#ifdef HEAP_V2_SHADOW
+    dump_profile("OOM");
+#endif
+  }
+  return p;
+}
+
+void pos_heap_v2::deallocate(void* ptr, size_t size) noexcept {
+  if (!ptr) return;
