+// Per-activation and aggregate result-block counts for one request.
+struct block_layout {
+  uint64_t full_per;    // full result blocks per activation
+  uint64_t pad_per;     // padding blocks per activation (0 or 1)
+  uint64_t full_total;  // total full blocks across all activations
+  uint64_t pad_total;   // total padding blocks across all activations
