+// Derive block_layout from request geometry.
+// Attention requests never have padding: all blocks are full.
+// Legacy matmuls without padding: all hbm_cnt blocks per activation are full.
+// Legacy matmuls with padding: the last block per activation is partial
+//   (pad_per is the ceiling of pad_bytes / res_bytes_per_block, always 1
+//   in practice since pad_bytes < res_bytes_per_block).
+inline block_layout compute_block_layout(bool attn_req,
+    uint64_t expected_blocks,
+    uint64_t res_bytes_per_block,
+    uint64_t pad_bytes,
+    uint32_t hbm_cnt,
+    size_t B) {
+  if (attn_req) return {expected_blocks, 0, expected_blocks, 0};
+  if (pad_bytes > 0) {
+    uint64_t pad_per = (res_bytes_per_block + pad_bytes - 1) / res_bytes_per_block;
+    return {hbm_cnt - pad_per, pad_per, expected_blocks - B, B};
+  }
+  return {hbm_cnt, 0, expected_blocks, 0};
+}
