+// by compute_block_layout to determine the per-activation full/pad split.
+inline bool prepare_and_stage_legacy(PosDevice* dev,
+    struct wqentry* workreq,
+    uint64_t prepare_wcmd_tail,
+    uint64_t prepare_acmd_tail,
+    uint64_t& expected_blocks,
