+    f.fields.wmem_sect = 0;
+    return f.value;
+  };
+  uint64_t full_legacy_identity = legacy_load_identity(wres_fields);
+  bool resident_legacy_wmem_sect = wres_fields.fields.wmem_sect;
+  hbm_cnt = wres_fields.fields.hbm_cnt;
+
