+      // zero hbm_stride to signal the FPGA to reuse resident weights.
+      weights_cmd_matmul_fields reuse_wcmd(wres_fields.value);
+      reuse_wcmd.fields.wmem_sect = dev->prev_legacy_wmem_sect;
+      reuse_wcmd.fields.hbm_stride = 0;
