+      // wcmd so the FPGA reads from the correct weight memory region.
+      ares_fields.fields.wmem_sect = reuse_wcmd.fields.wmem_sect;
+      resident_legacy_wmem_sect = dev->prev_legacy_wmem_sect;
+      // Undo the csector flip from prepare_cmd_words: no ping-pong happens
+      // on the reuse path so the sector must not advance.
+      dev->csector ^= (bool)(hbm_cnt % 2);
+      dev->legacy_wcmd_reuse_count.fetch_add(1, std::memory_order_relaxed);
