+  dev->wcmds[prepare_wcmd_tail % rxinfo_ring_size] = wres_fields.value;
+  dev->acmds[prepare_acmd_tail % rxinfo_ring_size] = ares_fields.value;
+  dev->wcmd_req_ids[prepare_wcmd_tail % rxinfo_ring_size] = workreq->request_id;
+  dev->acmd_req_ids[prepare_acmd_tail % rxinfo_ring_size] = workreq->request_id;
+  dbg_wlr_log("hw_prepare {}: staged legacy wcmd at index {}: {:#016x} {}", dev->addr(),
+      prepare_wcmd_tail, wres_fields.value, wres_fields.debug_string());
+  dbg_wlr_log("hw_prepare {}: staged legacy acmd at index {}: {:#016x} {}", dev->addr(),
+      prepare_acmd_tail, ares_fields.value, ares_fields.debug_string());
