+            workreq->debug_label, ai + 1, num_acmds,
+            dev->acmds[(prepare_acmd_tail + ai) % rxinfo_ring_size], acmd_desc_idx,
+            acmdf.debug_string(
+                dev->acmds[(prepare_acmd_tail + ai) % rxinfo_ring_size]));
+      } else {
+        att_activ_cmd_1_fields acmdf;
+        dbg_cmds_log(
+            "TX WORKER hw_prepare {}:{} ({}, {}) acmd {}/{} 0x{:016x} at desc {} {}",
+            dev->addr(), workreq->request_id, workreq->attn_req ? "hwattn" : "legacy",
+            workreq->debug_label, ai + 1, num_acmds,
+            dev->acmds[(prepare_acmd_tail + ai) % rxinfo_ring_size], acmd_desc_idx,
+            acmdf.debug_string(
+                dev->acmds[(prepare_acmd_tail + ai) % rxinfo_ring_size]));
+      }
+    } else {
+      att_activ_cmd_legacy_fields acmdf;
+      dbg_cmds_log("TX WORKER hw_prepare {}:{} ({}, {}) acmd 0x{:016x} at desc {} {}",
+          dev->addr(), workreq->request_id, workreq->attn_req ? "hwattn" : "legacy",
