+  dbg_tx_log("TX WORKER {}:{} ({}, {}) used {} descriptors for cmds and activations.",
+      dev->addr(), workreq->request_id, workreq->attn_req ? "hwattn" : "legacy",
+      workreq->debug_label, tx_desc_used);
