+  // The workers write their path bits through the span the visit loop hoists.
+  // job 0: AMX on worker 0 and AVX on worker 2; job 1: FPGA + AVX; job 2: FPGA
+  // only; job 3: nothing; job 4: AVX + AMX on one worker.
+  uint8_t* bits_w0 = stats->token_path_span(WORKER_0, N_TOKEN_JOBS_5);
+  uint8_t* bits_w1 = stats->token_path_span(WORKER_1, N_TOKEN_JOBS_5);
+  uint8_t* bits_w2 = stats->token_path_span(WORKER_2, N_TOKEN_JOBS_5);
+  bits_w0[0] |= path_bit(visit_path::amx);
+  bits_w2[0] |= path_bit(visit_path::avx);
+  bits_w1[1] |= path_bit(visit_path::avx);
+  stats->note_fpga_query(1);
+  stats->note_fpga_query(2);
+  bits_w1[4] |= path_bit(visit_path::avx);
+  bits_w1[4] |= path_bit(visit_path::amx);
+  bits_w0[4] |= path_bit(visit_path::empty);  // an empty visit adds no bit
+  stats->end_forward(N_TOKEN_JOBS_5);
+
+  forward_counters const& fc = stats->forwards[CLASS_DECODE_0];
+  CHECK(load_relaxed(fc.token_jobs) == N_TOKEN_JOBS_5);
+  CHECK(load_relaxed(fc.fpga_queries) == 2);
+  CHECK(load_relaxed(fc.token_jobs_by_path_set[PATH_BIT_AVX_1 | PATH_BIT_AMX_2]) == 2);
+  CHECK(load_relaxed(fc.token_jobs_by_path_set[PATH_BIT_FPGA_4 | PATH_BIT_AVX_1]) == 1);
+  CHECK(load_relaxed(fc.token_jobs_by_path_set[PATH_BIT_FPGA_4]) == 1);
+  CHECK(load_relaxed(fc.token_jobs_by_path_set[0]) == 1);
+  CHECK(
+      stats->render_forwards(CLASS_DECODE_0)
+          .find("\"fpga_queries\":2,\"token_jobs\":5,\"listener_jobs\":5,"
+                "\"kv_only_jobs\":0,\"n_attn_workers_min\":0,\"n_attn_workers_max\":0,"
+                "\"token_jobs_by_path_set\":{"
+                "\"none\":1,\"avx\":0,"
+                "\"amx\":0,\"avx+amx\":2,\"fpga\":1,\"fpga+avx\":1,\"fpga+amx\":0,"
+                "\"fpga+avx+amx\":0}}") != std::string::npos);
+  // The prompt class saw nothing.
+  CHECK(load_relaxed(stats->forwards[CLASS_PROMPT_1].token_jobs) == 0);
+
+  // The next forward begins with cleared bits: the same jobs with no visits count as
+  // "none".
+  stats->begin_forward(forward_class::prompt_or_mixed, N_TOKEN_JOBS_5, LISTENERS_1);
+  stats->end_forward(N_TOKEN_JOBS_5);
+  CHECK(load_relaxed(stats->forwards[CLASS_PROMPT_1].token_jobs_by_path_set[0]) ==
+        N_TOKEN_JOBS_5);
+  CHECK(load_relaxed(stats->forwards[CLASS_PROMPT_1].fpga_queries) == 0);
+  // The mix of the class: a prompt chunk of 5 jobs has one listener (its last
