+// Own the stats singleton for one test case; the tree is initialized but never
+// mounted (no /dev/fuse needed): get_value() runs the read callback directly.
+struct stats_environment {
+  std::string dir;
+  stats_environment() {
+    tron::fuse::stats::unmount();
+    std::string templ =
+        (std::filesystem::temp_directory_path() / "attn_stats_XXXXXX").string();
+    std::vector<char> buf(templ.begin(), templ.end());
+    buf.push_back('\0');
+    char* created = ::mkdtemp(buf.data());
+    REQUIRE(created != nullptr);
+    dir = created;
+    tron::fuse::stats::initialize(dir);
+  }
+  ~stats_environment() {
+    tron::fuse::stats::unmount();
+    std::error_code ec;
+    std::filesystem::remove_all(dir, ec);
