+TEST_CASE("attn-stats forward_scope: one object owns the per-forward record",
+    "[attn_stats]") {
+  // PR 4596 review round 4, comment W2: the record behind <class>_forwards
+  // had two writers, the scheduler (forwards and the wall) and the model
+  // (class, token jobs, path sets). forward_scope is the one owner. The class
+  // is stored at construction. The wall and the fold are recorded at
+  // destruction. So every caller of model::state::forward gets a whole record
+  // filed under the class of that forward.
+  auto stats = make_stats(STATS_ON_TRUE);
+  forward_counters const& decode = stats->forwards[CLASS_DECODE_0];
+  forward_counters const& prompt = stats->forwards[CLASS_PROMPT_1];
+  const uint64_t t_before = tron::hardware::system::rdtsc();
+  {
+    forward_scope scope(
+        *stats, forward_class::decode_like, N_TOKEN_JOBS_5, LISTENERS_ALL_5);
+    // Inside the forward: worker 0 serves job 0 on the AVX path, and the
+    // hardware plan gives job 1 an FPGA pass.
+    uint8_t* bits = stats->token_path_span(WORKER_0, N_TOKEN_JOBS_5);
+    bits[0] |= PATH_BIT_AVX_1;
+    stats->note_fpga_query(1);
+    // Forwards, token jobs and the wall are not filed before the scope ends.
+    // fpga_queries is filed at once by its own writer.
+    CHECK(load_relaxed(decode.fpga_queries) == 1);
+    CHECK(load_relaxed(decode.forwards) == 0);
+    CHECK(load_relaxed(decode.token_jobs) == 0);
+    CHECK(load_relaxed(decode.wall_cycles) == 0);
+  }
+  const uint64_t elapsed = tron::hardware::system::rdtsc() - t_before;
+  CHECK(load_relaxed(decode.forwards) == 1);
+  CHECK(load_relaxed(decode.token_jobs) == N_TOKEN_JOBS_5);
+  CHECK(load_relaxed(decode.listener_jobs) == LISTENERS_ALL_5);
+  CHECK(load_relaxed(decode.kv_only_jobs) == 0);
+  CHECK(load_relaxed(decode.fpga_queries) == 1);
+  CHECK(load_relaxed(decode.wall_cycles) > 0);
+  CHECK(load_relaxed(decode.wall_cycles) <= elapsed);
+  CHECK(load_relaxed(decode.wall_max_cycles) == load_relaxed(decode.wall_cycles));
+  CHECK(load_relaxed(decode.token_jobs_by_path_set[PATH_BIT_AVX_1]) == 1);
+  CHECK(load_relaxed(decode.token_jobs_by_path_set[PATH_BIT_FPGA_4]) == 1);
+  CHECK(load_relaxed(decode.token_jobs_by_path_set[0]) == 3);
+  CHECK(load_relaxed(prompt.forwards) == 0);
+  CHECK(load_relaxed(prompt.token_jobs) == 0);
+  // The wall is filed under the class the scope stored, never under the class
+  // of an earlier forward: a prompt forward after a decode forward.
+  {
+    forward_scope scope(
+        *stats, forward_class::prompt_or_mixed, N_TOKEN_JOBS_5, LISTENERS_1);
+  }
+  CHECK(load_relaxed(prompt.forwards) == 1);
+  CHECK(load_relaxed(prompt.token_jobs) == N_TOKEN_JOBS_5);
+  CHECK(load_relaxed(prompt.listener_jobs) == LISTENERS_1);
+  CHECK(load_relaxed(prompt.kv_only_jobs) == N_TOKEN_JOBS_5 - LISTENERS_1);
+  CHECK(load_relaxed(decode.forwards) == 1);
+  // Switch off: the scope writes nothing and the leaf reads {}.
+  auto off = make_stats(STATS_OFF_FALSE);
+  {
+    forward_scope scope(
+        *off, forward_class::decode_like, N_TOKEN_JOBS_5, LISTENERS_ALL_5);
+  }
+  CHECK(load_relaxed(off->forwards[CLASS_DECODE_0].forwards) == 0);
+  CHECK(load_relaxed(off->forwards[CLASS_DECODE_0].token_jobs) == 0);
+  CHECK(load_relaxed(off->forwards[CLASS_DECODE_0].listener_jobs) == 0);
+  CHECK(load_relaxed(off->forwards[CLASS_DECODE_0].kv_only_jobs) == 0);
+  CHECK(off->render_forwards(CLASS_DECODE_0) == "{}");
+}
