+TEST_CASE("attn-stats forwards record: the three job counts move together at the end "
+          "of the forward",
+    "[attn_stats]") {
+  // Seen in a live read of a CPU-attention run on 2026-09-29: listener_jobs
+  // was one forward ahead of token_jobs. begin_forward added the listener
+  // counts and end_forward added the token jobs. A reader of the leaves
+  // during a forward must never see listener_jobs + kv_only_jobs above
+  // token_jobs. All three are added in end_forward now. Under the old order
+  // the mid-forward CHECKs on listener_jobs, kv_only_jobs and the rendered
+  // leaf fail, for both classes below.
+  auto stats = make_stats(STATS_ON_TRUE);
+  forward_counters const& prompt = stats->forwards[CLASS_PROMPT_1];
+  stats->begin_forward(forward_class::prompt_or_mixed, N_TOKEN_JOBS_5, LISTENERS_1);
+  // Mid-forward: nothing filed yet.
+  CHECK(load_relaxed(prompt.listener_jobs) == 0);
+  CHECK(load_relaxed(prompt.kv_only_jobs) == 0);
+  CHECK(load_relaxed(prompt.token_jobs) == 0);
+  CHECK(stats->render_forwards(CLASS_PROMPT_1)
+            .find("\"token_jobs\":0,\"listener_jobs\":0,\"kv_only_jobs\":0,") !=
+        std::string::npos);
+  stats->end_forward(N_TOKEN_JOBS_5);
+  CHECK(load_relaxed(prompt.listener_jobs) == LISTENERS_1);
+  CHECK(load_relaxed(prompt.kv_only_jobs) == N_TOKEN_JOBS_5 - LISTENERS_1);
+  CHECK(load_relaxed(prompt.token_jobs) == N_TOKEN_JOBS_5);
+  // The listener count belongs to the forward that began, also when another
+  // class's forward follows: a decode forward adds 5 listener jobs and 0
+  // KV-only jobs to its own class.
+  forward_counters const& decode = stats->forwards[CLASS_DECODE_0];
+  stats->begin_forward(forward_class::decode_like, N_TOKEN_JOBS_5, LISTENERS_ALL_5);
+  CHECK(load_relaxed(decode.listener_jobs) == 0);
+  stats->end_forward(N_TOKEN_JOBS_5);
+  CHECK(load_relaxed(decode.listener_jobs) == LISTENERS_ALL_5);
+  CHECK(load_relaxed(decode.kv_only_jobs) == 0);
+  CHECK(load_relaxed(decode.token_jobs) == N_TOKEN_JOBS_5);
+  CHECK(load_relaxed(prompt.listener_jobs) == LISTENERS_1);
+}
