+TEST_CASE("attn-stats leaves: JSON with the expected keys, below the FUSE string limit",
+    "[attn_stats]") {
+  // A large model shape: many workers and layers must keep every leaf below
+  // fuse_sysfs::MAX_STRING_LENGTH, because every leaf is one layer or one
+  // worker, never the whole table.
+  constexpr size_t N_WORKERS_LARGE_96 = 96;
+  constexpr size_t N_LAYERS_LARGE_128 = 128;
+  // Digit-wide fill values: every counter of the leaf is this wide, so the
+  // rendered leaf is as long as it can get for the size check below.
+  constexpr uint64_t FILL_COUNT_123456789 = 123456789;
+  constexpr uint64_t FILL_CYCLES_123456789012345 = 123456789012345ULL;
+  auto stats = std::make_shared<model_stats>(STATS_ON_TRUE, "big-model",
+      NOT_EAGLE_FALSE, test_facts(), N_WORKERS_LARGE_96, N_LAYERS_LARGE_128);
+  visit_tally tally;
+  for (int i = 0; i < 1000; ++i)
+    tally.record(visit_path::amx, K_TOKENS_FULL_PAGE_64, PAGE_SIZE_64);
+  for (size_t w = 0; w < N_WORKERS_LARGE_96; ++w) {
+    for (size_t l = 0; l < N_LAYERS_LARGE_128; ++l) {
+      auto& r = stats->row(CLASS_DECODE_0, w, l);
+      r.add(tally, PASS_READY_0);
+      r.add(tally, PASS_PENDING_1);
+      inc_relaxed(r.attn_jobs, FILL_COUNT_123456789);
+      inc_relaxed(r.busy_cycles, FILL_CYCLES_123456789012345);
+      inc_relaxed(r.join_wait_cycles, FILL_CYCLES_123456789012345);
+    }
+  }
+  for (size_t l = 0; l < N_LAYERS_LARGE_128; ++l) {
+    auto& t = stats->timers_at(CLASS_DECODE_0, l);
+    for (auto* c : {&t.wall_cycles, &t.wall_max_cycles, &t.period_cycles,
+             &t.period_count, &t.period_max_cycles}) {
+      inc_relaxed(*c, FILL_CYCLES_123456789012345);
+    }
+  }
+  // The forwards record too, so its leaf is rendered at full width.
+  forward_counters& fc = stats->forwards[CLASS_DECODE_0];
+  for (auto* c : {&fc.forwards, &fc.wall_cycles, &fc.wall_max_cycles, &fc.fpga_queries,
+           &fc.token_jobs, &fc.listener_jobs, &fc.kv_only_jobs, &fc.n_attn_workers_max})
+    inc_relaxed(*c, FILL_CYCLES_123456789012345);
+  for (auto& c : fc.token_jobs_by_path_set)
+    inc_relaxed(c, FILL_CYCLES_123456789012345);
+  const std::string totals = stats->render_totals(CLASS_DECODE_0);
+  const std::string layer = stats->render_layer(CLASS_DECODE_0, LAYER_0);
+  const std::string worker = stats->render_worker(CLASS_DECODE_0, WORKER_0);
+  const std::string forwards = stats->render_forwards(CLASS_DECODE_0);
+  const std::string summary = stats->render_summary();
+  for (auto const* s : {&totals, &layer, &worker, &forwards, &summary}) {
+    CHECK(s->size() < tron::fuse::fuse_sysfs::MAX_STRING_LENGTH);
+    CHECK(s->front() == '{');
+    CHECK(s->back() == '}');
+  }
+  CHECK(totals.find("\"ready_amx_visits\":") != std::string::npos);
+  CHECK(totals.find("\"pending_avx_k_tokens\":") != std::string::npos);
+  CHECK(totals.find("\"fpga_k_tokens\":") != std::string::npos);
+  CHECK(totals.find("\"fpga_k_tokens_x_kv_heads\":") != std::string::npos);
+  CHECK(summary.find("\"active_workers\":96,") != std::string::npos);
+  CHECK(layer.find("\"layer\":0,") != std::string::npos);
+  CHECK(worker.find("\"worker\":0,") != std::string::npos);
+  // The T3/T4 keys are per layer: in the layer and totals leaves, not in the
+  // worker leaf.
+  CHECK(layer.find("\"wall_cycles_w0\":") != std::string::npos);
+  CHECK(layer.find("\"period_count_w0\":") != std::string::npos);
+  CHECK(totals.find("\"wall_cycles_w0\":") != std::string::npos);
+  CHECK(worker.find("\"wall_cycles_w0\":") == std::string::npos);
+  CHECK(worker.find("\"period_count_w0\":") == std::string::npos);
+  CHECK(worker.find("\"join_wait_cycles\":") != std::string::npos);
+  CHECK(forwards.find("\"listener_jobs\":") != std::string::npos);
+  CHECK(forwards.find("\"kv_only_jobs\":") != std::string::npos);
+  CHECK(forwards.find("\"n_attn_workers_min\":") != std::string::npos);
+  CHECK(forwards.find("\"n_attn_workers_max\":") != std::string::npos);
+  CHECK(forwards.find("\"token_jobs_by_path_set\":{\"none\":") != std::string::npos);
+  CHECK(summary.find("\"switch\":\"TRON_ATTN_STATS=1\"") != std::string::npos);
+  // The layer leaf carries the sum over the 96 workers.
+  const std::string expected =
+      fmt::format("\"ready_amx_visits\":{},", 1000 * N_WORKERS_LARGE_96);
+  CHECK(layer.find(expected) != std::string::npos);
+}
