+TEST_CASE("attn-stats FUSE leaves: registered once per model id, read live, empty "
+          "after the state is gone",
+    "[attn_stats]") {
+  stats_environment env;
+  const std::string prefix = "/model/test-model/attention";
+  {
+    auto stats = make_stats(STATS_ON_TRUE);
+    register_fuse_files(stats);
+    CHECK(leaf_string(prefix + "/summary").find("\"on\":true") != std::string::npos);
+    // No marker files: casual leaves carry no tronstats convention obligation.
+    CHECK_FALSE(tron::fuse::stats::get_file_handle(prefix + "/.skip"));
+    // The next read carries the new counts: no reset.
+    visit_tally tally;
+    tally.record(visit_path::avx, K_TOKENS_TAIL_17, PAGE_SIZE_64);
+    stats->row(CLASS_DECODE_0, WORKER_0, LAYER_0).add(tally, PASS_READY_0);
+    CHECK(leaf_string(prefix + "/decode_like_totals").find("\"ready_avx_visits\":1,") !=
+          std::string::npos);
+    CHECK(leaf_string(prefix + "/decode_like_layer_0")
+              .find("\"ready_avx_k_tokens\":17,") != std::string::npos);
+    CHECK(
+        leaf_string(prefix + "/decode_like_worker_0").find("\"ready_avx_visits\":1,") !=
+        std::string::npos);
+    CHECK(leaf_string(prefix + "/prompt_or_mixed_totals")
+              .find("\"ready_avx_visits\":0,") != std::string::npos);
+    // The layer leaf exists for every layer of the model, and not beyond.
+    CHECK(tron::fuse::stats::get_file_handle(prefix + "/decode_like_layer_3"));
+    CHECK_FALSE(tron::fuse::stats::get_file_handle(prefix + "/decode_like_layer_4"));
+    {
+      // A later state of the same model id takes the leaves over (runtron
+      // builds one state per prompt batch); when it dies the leaves read as
+      // empty although the first state is still alive.
+      auto twin = make_stats(STATS_ON_TRUE);
+      register_fuse_files(twin);
+      CHECK(
+          leaf_string(prefix + "/decode_like_totals").find("\"ready_avx_visits\":0,") !=
+          std::string::npos);
+      twin->row(CLASS_DECODE_0, WORKER_1, LAYER_0).add(tally, PASS_PENDING_1);
+      CHECK(leaf_string(prefix + "/decode_like_totals")
+                .find("\"pending_avx_visits\":1,") != std::string::npos);
+    }
+    CHECK(leaf_string(prefix + "/decode_like_totals") == "{}");
+    // Re-registering the surviving state brings its numbers back.
+    register_fuse_files(stats);
+    CHECK(leaf_string(prefix + "/decode_like_totals").find("\"ready_avx_visits\":1,") !=
+          std::string::npos);
+  }
+  // The state is gone: the leaves stay but read as an empty object.
+  CHECK(leaf_string(prefix + "/summary") == "{}");
+  CHECK(leaf_string(prefix + "/decode_like_totals") == "{}");
+}
