+  CHECK_FALSE(tron::fuse::stats::get_file_handle(prefix + "/decode_like_worker_0"));
+  // Ids that cannot be one path segment are skipped without registering anything.
+  // The validator itself: empty, leading dot and a slash fail; the character
+  // classes of an ingested id (letters, digits, dash, dot, underscore, colon)
+  // pass. Made-up ids: a real model slug in a test source trips the CMake
+  // model-requirement audit.
+  CHECK_FALSE(is_safe_model_id(""));
+  CHECK_FALSE(is_safe_model_id(".hidden"));
+  CHECK_FALSE(is_safe_model_id("a/b"));
+  CHECK(is_safe_model_id("ingested-sample-3-4b-instruct-2507-tp2"));
+  CHECK(is_safe_model_id("sample-3.1:8b_v2"));
+  auto bad = make_stats(STATS_ON_TRUE, "a/b");
+  register_fuse_files(bad);
+  CHECK_FALSE(tron::fuse::stats::get_file_handle("/model/a/b/attention/summary"));
+}
